import numpy as np

def pack(arr):
    a = np.asarray(arr)
    # Convert complex NaNs to a canonical complex dtype array for serialization.
    return a.tolist()

res = {}
# 1) real inf..inf
res['linspace_inf_inf_5'] = pack(np.linspace(np.inf, np.inf, 5))

# 2) real inf..inf retstep
y, step = np.linspace(np.inf, np.inf, 2, retstep=True)
res['linspace_inf_inf_2_retstep'] = {
    'y': pack(y),
    'step': float(step) if np.isfinite(step) else str(step)
}

# 3) -inf..-inf
res['linspace_neg_inf_neg_inf_3'] = pack(np.linspace(-np.inf, -np.inf, 3))

# 4) complex(inf,0)..complex(inf,0)
z1 = complex(np.inf, 0)
z2 = complex(np.inf, 0)
res['linspace_complex_inf_inf_3'] = pack(np.linspace(z1, z2, 3))

# Also capture whether any RuntimeWarning/invalid occurred is outside tool capture;
# instead capture exact nan/inf pattern.

def nan_mask(x):
    x = np.asarray(x)
    return np.isnan(x).tolist()

def inf_mask(x):
    x = np.asarray(x)
    return np.isinf(x).tolist()

res['masks_1'] = {'nan': nan_mask(np.linspace(np.inf, np.inf, 5)), 'inf': inf_mask(np.linspace(np.inf, np.inf, 5))}
res['masks_3'] = {'nan': nan_mask(np.linspace(-np.inf, -np.inf, 3)), 'inf': inf_mask(np.linspace(-np.inf, -np.inf, 3))}

probe('equal_inf_linspace_report_examples', res)

